(5838542, 850056, 78652, '<td valign="top">Like the B&amp;W.  I like the toning.  My favorite of this challenge.</td>', 'Like the B&W.  I like the toning.  My favorite of this challenge.', '2010-01-27 17:56:51.000000', NULL, 1),
(5838543, 849035, 78652, '<td valign="top">Like the busy feel of this photo.  Wish I could see more faces and their reactions to what''s going on all around.  One of my favorites.</td>', 'Like the busy feel of this photo.  Wish I could see more faces and their reactions to what''s going on all around.  One of my favorites.', '2010-01-27 17:57:46.000000', NULL, 1),
(5838546, 850143, 78652, '<td valign="top">Like the fact that there is so much to see.  Perhaps this could''ve been taken at a time with a lot more people filling the scene to match the business of everything else around..Like the desaturated look to this photo.</td>', 'Like the fact that there is so much to see.  Perhaps this could''ve been taken at a time with a lot more people filling the scene to match the business of everything else around..Like the desaturated look to this photo.', '2010-01-27 17:59:13.000000', NULL, 1),
(5838550, 849184, 78652, '<td valign="top">Seems like the focus is on the recreation at the center of the photo.  Would''ve loved to see the chess game closer.  Nice shot.</td>', 'Seems like the focus is on the recreation at the center of the photo.  Would''ve loved to see the chess game closer.  Nice shot.', '2010-01-27 18:00:56.000000', NULL, 1),
(5838554, 848802, 78652, '<td valign="top">Any shots including the other side of the roadway?  Nice scenery.</td>', 'Any shots including the other side of the roadway?  Nice scenery.', '2010-01-27 18:03:26.000000', NULL, 1),
(5838558, 850123, 78652, '<td valign="top">Would''ve loved to see a higher perspective, perhaps with the sign at eye level and a bit brighter to emphasize where this photo is.  Nice shot.</td>', 'Would''ve loved to see a higher perspective, perhaps with the sign at eye level and a bit brighter to emphasize where this photo is.  Nice shot.', '2010-01-27 18:05:33.000000', NULL, 1),
(5838562, 849462, 78652, '<td valign="top">I''m drawn towards the bright area of the skyline.  Scenic shot.</td>', 'I''m drawn towards the bright area of the skyline.  Scenic shot.', '2010-01-27 18:09:03.000000', NULL, 1),
(5838566, 849559, 78652, '<td valign="top">Any shots with a slower shutter?  Might be neat to see what motion blur could''ve done with this shot.</td>', 'Any shots with a slower shutter?  Might be neat to see what motion blur could''ve done with this shot.', '2010-01-27 18:10:53.000000', NULL, 1),
(5838647, 850147, 47541, '<td valign="top">Interesting concept but I think having all those trees doesn''t allow the glow idea to fully come through</td>', 'Interesting concept but I think having all those trees doesn''t allow the glow idea to fully come through', '2010-01-27 18:43:41.000000', NULL, 1),
(5838649, 849185, 47541, '<td valign="top">Nice vivid colours!</td>', 'Nice vivid colours!', '2010-01-27 18:43:58.000000', NULL, 1),
(5838651, 849735, 47541, '<td valign="top">I love the tones but the processing has spoilt the shot - too much noise reduction or sharpening perhaps?</td>', 'I love the tones but the processing has spoilt the shot - too much noise reduction or sharpening perhaps?', '2010-01-27 18:44:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5838652, 849775, 47541, '<td valign="top">When I read the title I immediately start singing! Nice shot, good DOF, good POV, poor composition - the two towers dwarf the people and become a competing feature</td>', 'When I read the title I immediately start singing! Nice shot, good DOF, good POV, poor composition - the two towers dwarf the people and become a competing feature', '2010-01-27 18:45:51.000000', NULL, 1),
(5838671, 850070, 47541, '<td valign="top">Nice capture of the tree lights, the surrounding add a lot of interest to the shot</td>', 'Nice capture of the tree lights, the surrounding add a lot of interest to the shot', '2010-01-27 18:54:26.000000', NULL, 1),
(5838672, 850138, 47541, '<td valign="top">Good composition, nice colours, seems to be lacking a little sharpness</td>', 'Good composition, nice colours, seems to be lacking a little sharpness', '2010-01-27 18:55:15.000000', NULL, 1),
(5838673, 849035, 47541, '<td valign="top">Great road to use, very busy and the shot shows this. I''m sure it''s not easy without climbing one of those trees but a different POV would have made this even better</td>', 'Great road to use, very busy and the shot shows this. I''m sure it''s not easy without climbing one of those trees but a different POV would have made this even better', '2010-01-27 18:55:58.000000', NULL, 1),
(5838675, 849469, 47541, '<td valign="top">One of the better light trail shots in the challenge, lots of interest in the shot</td>', 'One of the better light trail shots in the challenge, lots of interest in the shot', '2010-01-27 18:56:39.000000', NULL, 1),
(5838679, 849941, 47541, '<td valign="top">Oh my, a monkeys bum! Good to see a unique POV used but the monkeys steals the shot</td>', 'Oh my, a monkeys bum! Good to see a unique POV used but the monkeys steals the shot', '2010-01-27 18:57:10.000000', NULL, 1),
(5838680, 850087, 47541, '<td valign="top">DNMC sorry, that ain''t a road</td>', 'DNMC sorry, that ain''t a road', '2010-01-27 18:57:35.000000', NULL, 1),
(5838685, 850089, 47541, '<td valign="top">What an interesting store - it makes me want to see more of it. The shot it ok but doesn''t really show the essence of the road</td>', 'What an interesting store - it makes me want to see more of it. The shot it ok but doesn''t really show the essence of the road', '2010-01-27 18:58:25.000000', NULL, 1),
(5838688, 850008, 47541, '<td valign="top">ok light trail shot but the crossing of them is great!</td>', 'ok light trail shot but the crossing of them is great!', '2010-01-27 18:58:52.000000', NULL, 1),
(5838716, 849964, 98647, '<td valign="top">Great leading lines. I like the processing.</td>', 'Great leading lines. I like the processing.', '2010-01-27 19:24:28.000000', NULL, 1),
(5838721, 850057, 98647, '<td valign="top">That curved pole is a bit weird.</td>', 'That curved pole is a bit weird.', '2010-01-27 19:27:03.000000', NULL, 1),
