(5838731, 850091, 98647, '<td valign="top">I like the tones but not the tilt.</td>', 'I like the tones but not the tilt.', '2010-01-27 19:29:20.000000', NULL, 1),
(5838733, 850056, 33672, '<td valign="top">Perfect tones.</td>', 'Perfect tones.', '2010-01-27 19:30:05.000000', NULL, 1),
(5838739, 850028, 33672, '<td valign="top">I live and travel with lonely planet.</td>', 'I live and travel with lonely planet.', '2010-01-27 19:32:34.000000', NULL, 1),
(5838745, 849035, 98647, '<td valign="top">This shot really tells you about the congestion of both people and vehicles. I don''t like the processing though.</td>', 'This shot really tells you about the congestion of both people and vehicles. I don''t like the processing though.', '2010-01-27 19:33:21.000000', NULL, 1),
(5838755, 850062, 98647, '<td valign="top">Love the tones.</td>', 'Love the tones.', '2010-01-27 19:35:20.000000', NULL, 1),
(5838769, 849055, 98647, '<td valign="top">Could be interesting but the processing is not helping the shot. Also a bit too centred.</td>', 'Could be interesting but the processing is not helping the shot. Also a bit too centred.', '2010-01-27 19:41:07.000000', NULL, 1),
(5838772, 849933, 47541, '<td valign="top">I can see the life of the market in the shot but I can''t help feeling that you''ve missed a good opportunity to really tell us something. Currently it feels like you thought the flowers would make a nice colourful shot so they are the focal point of the shot with the street and the rest of the market as an afterthought to meet challenge</td>', 'I can see the life of the market in the shot but I can''t help feeling that you''ve missed a good opportunity to really tell us something. Currently it feels like you thought the flowers would make a nice colourful shot so they are the focal point of the shot with the street and the rest of the market as an afterthought to meet challenge', '2010-01-27 19:41:46.000000', NULL, 1),
(5838774, 849589, 47541, '<td valign="top">Nice shot, doesn''t really show the essence of the street though</td>', 'Nice shot, doesn''t really show the essence of the street though', '2010-01-27 19:42:15.000000', NULL, 1),
(5838777, 850076, 47541, '<td valign="top">Neat effect with that lens (fisheye?)</td>', 'Neat effect with that lens (fisheye?)', '2010-01-27 19:42:45.000000', NULL, 1),
