(5840214, 849912, 37529, '<td valign="top">Cool.  Looks like you''re a night owl.  Nice shot.</td>', 'Cool.  Looks like you''re a night owl.  Nice shot.', '2010-01-28 09:22:31.000000', NULL, 1),
(5840272, 849964, 114021, '<td valign="top">Good sharpness and nice composition. Black and white and grey shades are looking fantastic! The crisp glitter of the street lights and the streaks of the vehicla lights indicate a perfect aperture and shutter speed setting ! Good work !</td>', 'Good sharpness and nice composition. Black and white and grey shades are looking fantastic! The crisp glitter of the street lights and the streaks of the vehicla lights indicate a perfect aperture and shutter speed setting ! Good work !', '2010-01-28 10:17:36.000000', NULL, 1),
(5840275, 850119, 114021, '<td valign="top">Really shows the speed at which the car is being driven. Good example of a miz of stationary and moving subjects and a moving camera !</td>', 'Really shows the speed at which the car is being driven. Good example of a miz of stationary and moving subjects and a moving camera !', '2010-01-28 10:19:33.000000', NULL, 1),
(5840277, 850105, 114021, '<td valign="top">There is something that is intriguing about this picture. It leaves me with a felling of wanting to see more .. interesting composition.</td>', 'There is something that is intriguing about this picture. It leaves me with a felling of wanting to see more .. interesting composition.', '2010-01-28 10:22:07.000000', NULL, 1),
